// topUpMatchedArchiveBlobs walks the matched archive's tree and fetches any
// blobs missing from the local object store. The probe fetch in
// fetchRelatedRemoteRotationArchive uses --filter=blob:none, so trees are
// present but blobs may not be; downstream code (updateGenerationTimestamps,
// the push that follows) needs them locally.
func topUpMatchedArchiveBlobs(ctx context.Context, fetchTarget string, repo *git.Repository, archiveTree *object.Tree) error {
	missing, err := missingBlobHashesInTree(repo, archiveTree)
	if err != nil {
		return err
	}
	if len(missing) == 0 {
		return nil
	}
	if err := remote.FetchBlobs(ctx, fetchTarget, missing); err != nil {
		return fmt.Errorf("fetch matched archive blobs: %w", err)
	}
	return nil
}

// missingBlobHashesInTree returns hex hashes of blobs reachable from tree
// (and its subtrees) that are not present in the local object store.
func missingBlobHashesInTree(repo *git.Repository, tree *object.Tree) ([]string, error) {
	seen := make(map[plumbing.Hash]struct{})
	var missing []string
	var walk func(t *object.Tree) error
	walk = func(t *object.Tree) error {
		for _, entry := range t.Entries {
			if entry.Mode == filemode.Dir {
				sub, err := repo.TreeObject(entry.Hash)
				if err != nil {
					return fmt.Errorf("read subtree %s: %w", entry.Name, err)
				}
				if err := walk(sub); err != nil {
					return err
				}
				continue
			}
			if _, ok := seen[entry.Hash]; ok {
				continue
			}
			seen[entry.Hash] = struct{}{}
			if repo.Storer.HasEncodedObject(entry.Hash) != nil {
				missing = append(missing, entry.Hash.String())
			}
		}
		return nil
	}
	if err := walk(tree); err != nil {
		return nil, err
	}
	return missing, nil
}

