		}
		successfulRefs = appendUniqueRef(successfulRefs, result.refName)
		if !result.result.upToDate {
			pushedContent = true
		}
	}

	if len(failures) > 0 {
		printV2PushFailures(ctx, target, successfulRefs, failures, pushedContent)
