	publishPendingSpan.RecordError(pendingPublishErr)
}
publishPendingSpan.End()
successfulRefs = append(successfulRefs, pendingPublicationResult.successfulRefs...)
if len(pendingPublicationResult.successfulRefs) > 0 {
	pushedContent = true
}
